import heapq

class Leaderboard:
    def __init__(self):
        self.scores = {}

    def addScore(self, playerId: int, score: int) -> None:
        self.scores[playerId] = self.scores.get(playerId, 0) + score

    def top(self, K: int) -> int:
        heap = []
        for s in self.scores.values():
            heapq.heappush(heap, s)
            if len(heap) > K:
                heapq.heappop(heap)
        return sum(heap)

    def reset(self, playerId: int) -> None:
        if playerId in self.scores:
            del self.scores[playerId]

class Leaderboard {
    unordered_map<int, int> scores;
public:
    Leaderboard() {}
    void addScore(int playerId, int score) {
        scores[playerId] += score;
    }
    int top(int K) {
        priority_queue<int, vector<int>, greater<int>> minHeap;
        for (auto& [_, s] : scores) {
            minHeap.push(s);
            if (minHeap.size() > K) minHeap.pop();
        }
        int sum = 0;
        while (!minHeap.empty()) {
            sum += minHeap.top();
            minHeap.pop();
        }
        return sum;
    }
    void reset(int playerId) {
        scores.erase(playerId);
    }
};

class Leaderboard {
    private final Map<Integer, Integer> scores = new HashMap<>();

    public void addScore(int playerId, int score) {
        scores.put(playerId, scores.getOrDefault(playerId, 0) + score);
    }

    public int top(int K) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int s : scores.values()) {
            pq.offer(s);
            if (pq.size() > K) pq.poll();
        }
        int sum = 0;
        while (!pq.isEmpty()) sum += pq.poll();
        return sum;
    }

    public void reset(int playerId) {
        scores.remove(playerId);
    }
}

class Leaderboard {
    constructor() {
        this.scores = new Map();
    }
    addScore(playerId, score) {
        this.scores.set(playerId, (this.scores.get(playerId) || 0) + score);
    }
    top(K) {
        const sorted = Array.from(this.scores.values()).sort((a, b) => b - a);
        let sum = 0;
        for (let i = 0; i < Math.min(K, sorted.length); i++) {
            sum += sorted[i];
        }
        return sum;
    }
    reset(playerId) {
        this.scores.delete(playerId);
    }
}
